package io.lumine.mythic.lib.script.mechanic.offense;import io.lumine.mythic.lib.script.mechanic.RawMechanic;import io.lumine.mythic.lib.util.configobject.ConfigObject;public class SetNoDamageTicksMechanic extends RawMechanic{public SetNoDamageTicksMechanic(ConfigObject c){super("set_no_damage_ticks"+render(c));}private static String render(ConfigObject c){if(c==null||c.getKeys().isEmpty())return "";StringBuilder b=new StringBuilder("{");boolean first=true;for(String k:c.getKeys()){if(!first)b.append(';');first=false;b.append(k).append('=').append(c.getString(k,""));}return b.append('}').toString();}}